cd /tmp && cat > cmp.mjs <<'EOF'
const oldM = await import('./old.ts');
const newM = await import('./new.ts');
function makeRaw() {
  const units=['uV','mV','V'];
  const readings=[];
  const n=3+Math.floor(Math.random()*8);
  for(let i=0;i<n;i++){
    let val;
    const r=Math.random();
    if(r<0.2)val=Math.floor(Math.random()*2000);
    else if(r<0.5)val=-Math.floor(Math.random()*50);
    else if(r<0.7)val=Math.floor(Math.random()*900);
    else if(r<0.8)val=1500+Math.floor(Math.random()*500);
    else val=Math.trunc(Math.random()*3000);
    readings.push({channel:'ch'+(i%3),unit:units[Math.floor(Math.random()*3)],value:val,at:Math.floor(Math.random()*100000)});
  }
  return {readings};
}
function seed(){return 42+Math.floor(Math.random()*100000);}
function shuffle(raw){for(let i=raw.readings.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[raw.readings[i],raw.readings[j]]=[raw.readings[j],raw.readings[i]];}return raw;}
let fails=0;
function eq(a,b,ctx){const ja=JSON.stringify(a),jb=JSON.stringify(b);if(ja!==jb){fails++;if(fails<10)console.log('MISMATCH',ctx,ja,jb);}}
// fuzz valid inputs
for(let t=0;t<20000;t++){
  const raw=makeRaw();
  eq(oldM.processBatch(raw),newM.processBatch(raw),'valid#t');
}
// fuzz malformed
const malformed=[null,undefined,1,'x',{}, {readings:'x'}, {readings:[]}, {readings:Array(501).fill({channel:'a',unit:'V',value:1,at:0})}];
for(const m of malformed) eq(oldM.processBatch(m),newM.processBatch(m),'malformed');
for(let t=0;t<20000;t++){
  const raw=makeRaw();
  const rr=raw.readings;
  if(rr.length&&Math.random()<0.5){
    const i=Math.floor(Math.random()*rr.length);
    const pick=Math.random();
    let bad;
    if(pick<0.25)bad={channel:'',unit:'V',value:1,at:0};
    else if(pick<0.4)bad={channel:'a',unit:'X',value:1,at:0};
    else if(pick<0.55)bad={channel:'a',unit:'V',value:1.5,at:0};
    else if(pick<0.7)bad={channel:'a',unit:'V',value:1,at:-1};
    else if(pick<0.8)bad=5;
    else if(pick<0.9)bad={channel:7,unit:'V',value:1,at:0};
    else bad={channel:'a',unit:'V',value:1,at:'x'};
    rr[i]=bad;
  }
  eq(oldM.processBatch(raw),newM.processBatch(raw),'bad#t');
}
// direct classifySignal fuzz
for(let t=0;t<50000;t++){
  const v=Math.floor(Math.random()*3000)-100;
  eq(oldM.classifySignal(v),newM.classifySignal(v),'classify');
}
console.log(fails===0?'ALL EQUAL':('FAILS='+fails));
